package dev.jackteng.encore;
import dev.jackteng.encore.catalog.*;
import dev.jackteng.encore.catalog.Models.*;
import dev.jackteng.encore.customer.CustomerService;
import dev.jackteng.encore.customer.CustomerService.Principal;
import dev.jackteng.encore.orders.*;
import dev.jackteng.encore.orders.OrderModels.*;
import dev.jackteng.encore.orders.PurchaseModels.Purchase;
import dev.jackteng.encore.common.ApiErrors.Problem;
import dev.jackteng.encore.admission.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.data.redis.core.StringRedisTemplate;
import jakarta.servlet.http.Cookie;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.purchases.deadline-seconds=60","ticket.admission.enabled=false","ticket.expiry.enabled=false","ticket.mock-payments.enabled=true"})
@AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class PurchaseIntegrationTest {
 @Autowired PurchaseService purchases;@Autowired OrderService orders;@Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired PaymentService payments;
 @Autowired JdbcTemplate db;@Autowired ObjectMapper json;@Autowired PlatformTransactionManager transactions;@Autowired MockMvc mvc;@Autowired StringRedisTemplate redis;
 String manager="purchase-manager-"+UUID.randomUUID();
 record Fixture(Event event,Session session,Ticket ticket) {}
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"synthetic unused hash","MANAGER");
  // Wait for this context's real Redis client, not just the container health check.
  long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);boolean ready=false;
  while(System.nanoTime()<deadline){try(var connection=redis.getConnectionFactory().getConnection()){if("PONG".equals(connection.ping())){ready=true;break;}}catch(RuntimeException e){try{Thread.sleep(100);}catch(InterruptedException x){throw new AssertionError(x);}}}
  assertTrue(ready,"Purchase test context Redis client must be ready before admission assertions");
 }
 Principal customer(){var issue=customers.register("p-"+UUID.randomUUID().toString().substring(0,30),"合成購票",UUID.randomUUID().toString());return customers.authenticate(issue.token()).orElseThrow();}
 Fixture fixture(int capacity,int limit){return fixture(capacity,limit,OffsetDateTime.now().plusHours(1),true);}
 Fixture fixture(int capacity,int limit,OffsetDateTime end,boolean publish){var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"purchase-"+UUID.randomUUID(),"購票演出","合成資料","合成場地"));var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成場次",end.plusDays(1),OffsetDateTime.now().minusHours(1),end));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般票",1200,capacity,limit));if(publish)e=catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);return new Fixture(e,s,t);}
 Place place(Fixture f,int quantity){return new Place(UUID.randomUUID(),f.ticket().id(),quantity,1,1200*quantity);}
 UUID event(Purchase p){return db.queryForObject("SELECT id FROM purchase_outbox WHERE purchase_id=?",UUID.class,p.id());}
 int held(Fixture f){return db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,f.ticket().id());}
 int count(String table,UUID owner){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE customer_id=?",Integer.class,owner);}
 void problem(String code,Runnable run){assertEquals(code,assertThrows(Problem.class,run::run).code);}
 void due(Purchase p){db.update("WITH stamp AS MATERIALIZED(SELECT clock_timestamp() AS clock) UPDATE purchase_request SET created_at=clock-interval '70 seconds',deadline_at=clock-interval '10 seconds' FROM stamp WHERE id=?",p.id());}
 @Test void acceptanceIsDurableIntentWithoutHold(){var c=customer();var f=fixture(2,2);var body=place(f,1);var p=purchases.submit(c,body);assertEquals("PROCESSING",p.status());assertNull(p.orderId());assertEquals(1,p.version());assertEquals(Duration.ofSeconds(60),Duration.between(p.createdAt(),p.deadlineAt()));assertEquals(0,held(f));assertEquals(0,count("ticket_order",c.id()));assertEquals(1,count("purchase_command",c.id()));assertNotNull(event(p));assertEquals(p,purchases.submit(c,body));}
 @Test void processingUsesSharedStockCoreAndStartsPaymentAtActualHold(){var c=customer();var f=fixture(2,2);var body=place(f,1);var p=purchases.submit(c,body);assertTrue(purchases.process(event(p)));var result=purchases.detail(c,p.id());var o=orders.detail(c,result.orderId());assertEquals("RESERVED",result.status());assertEquals(2,result.version());assertTrue(!o.createdAt().isBefore(p.createdAt()));assertEquals(Duration.ofMinutes(10),Duration.between(o.createdAt(),o.expiresAt()));assertEquals(body.requestId(),o.requestId());assertEquals(1,held(f));assertFalse(purchases.process(event(p)));assertEquals(o,orders.place(c,body));assertEquals(result,purchases.submit(c,body));}
 @Test void concurrentSameSubmitUUIDCreatesOneOutbox()throws Exception {var c=customer();var f=fixture(8,8);var body=place(f,1);try(var pool=Executors.newFixedThreadPool(6)){var calls=new ArrayList<Callable<Purchase>>();for(int i=0;i<6;i++)calls.add(()->purchases.submit(c,body));UUID id=null;for(var r:pool.invokeAll(calls)){if(id==null)id=r.get().id();assertEquals(id,r.get().id());}}assertEquals(1,count("purchase_request",c.id()));assertEquals(0,held(f));assertEquals(1,db.queryForObject("SELECT count(*) FROM purchase_outbox o JOIN purchase_request p ON p.id=o.purchase_id WHERE p.customer_id=?",Integer.class,c.id()));}
 @Test void concurrentDuplicateDeliveryReservesOnce()throws Exception {var c=customer();var f=fixture(4,4);var p=purchases.submit(c,place(f,1));UUID e=event(p);try(var pool=Executors.newFixedThreadPool(6)){var calls=new ArrayList<Callable<Boolean>>();for(int i=0;i<6;i++)calls.add(()->purchases.process(e));int winners=0;for(var r:pool.invokeAll(calls))if(r.get())winners++;assertEquals(1,winners);}assertEquals(1,held(f));assertEquals(1,count("ticket_order",c.id()));}
 @Test void sharedLastTicketSyncAndAsyncRaceHasOneWinner()throws Exception {var f=fixture(1,1);var a=customer();var b=customer();var p=purchases.submit(a,place(f,1));try(var pool=Executors.newFixedThreadPool(2)){for(var r:pool.invokeAll(List.<Callable<Object>>of(()->purchases.process(event(p)),()->{try{return orders.place(b,place(f,1));}catch(Problem x){assertEquals("SOLD_OUT",x.code);return null;}})))r.get();}assertEquals(1,held(f));var result=purchases.detail(a,p.id());assertTrue(Set.of("RESERVED","REJECTED").contains(result.status()));if(result.status().equals("REJECTED"))assertEquals("SOLD_OUT",result.reason());}
 @Test void sameUUIDChangedBodyOrActionRejected(){var c=customer();var f=fixture(2,2);var body=place(f,1);var p=purchases.submit(c,body);problem("REQUEST_CONFLICT",()->purchases.submit(c,new Place(body.requestId(),body.ticketId(),2,1,2400)));problem("REQUEST_CONFLICT",()->purchases.cancel(c,p.id(),new Cancel(body.requestId(),1)));problem("REQUEST_CONFLICT",()->orders.place(c,body));assertEquals(0,held(f));}
 @Test void syncFirstUUIDCannotCreateAsyncIntent(){var c=customer();var f=fixture(2,2);var body=place(f,1);orders.place(c,body);problem("REQUEST_CONFLICT",()->purchases.submit(c,body));assertEquals(0,count("purchase_request",c.id()));}
 @Test void sameUUIDIsScopedToCustomer(){var f=fixture(2,2);var body=place(f,1);var a=purchases.submit(customer(),body);var b=purchases.submit(customer(),body);assertNotEquals(a.id(),b.id());}
 @Test void ownerCannotReadCancelOrListOthers(){var a=customer();var b=customer();var p=purchases.submit(a,place(fixture(2,2),1));problem("NOT_FOUND",()->purchases.detail(b,p.id()));problem("NOT_FOUND",()->purchases.cancel(b,p.id(),new Cancel(UUID.randomUUID(),1)));assertEquals(0,purchases.list(b,1,10).total());assertEquals(1,purchases.list(a,1,10).total());problem("INVALID_INPUT",()->purchases.list(a,1,21));}
 @Test void maximumFiveProcessingRequestsAndCancellationFreesSlot(){var c=customer();var f=fixture(10,10);Purchase first=null;for(int i=0;i<5;i++){var p=purchases.submit(c,place(f,1));if(first==null)first=p;}problem("REQUEST_LIMIT",()->purchases.submit(c,place(f,1)));purchases.cancel(c,first.id(),new Cancel(UUID.randomUUID(),1));assertNotNull(purchases.submit(c,place(f,1)));assertEquals(0,held(f));}
 @Test void cancellationReplaysAndNeverRevivesOrCreatesOrder(){var c=customer();var f=fixture(2,2);var body=place(f,1);var p=purchases.submit(c,body);var cancel=new Cancel(UUID.randomUUID(),1);var result=purchases.cancel(c,p.id(),cancel);assertEquals("CANCELLED",result.status());assertEquals(result,purchases.cancel(c,p.id(),cancel));assertEquals(result,purchases.submit(c,body));assertFalse(purchases.process(event(p)));assertEquals(0,held(f));problem("STALE_VERSION",()->purchases.cancel(c,p.id(),new Cancel(UUID.randomUUID(),1)));}
 @Test void cancelDeliveryRaceEndsCancelledOrSingleReserved()throws Exception {var c=customer();var f=fixture(2,2);var p=purchases.submit(c,place(f,1));try(var pool=Executors.newFixedThreadPool(2)){for(var r:pool.invokeAll(List.<Callable<Object>>of(()->purchases.process(event(p)),()->{try{return purchases.cancel(c,p.id(),new Cancel(UUID.randomUUID(),1));}catch(Problem x){assertTrue(Set.of("STALE_VERSION","ORDER_CREATED").contains(x.code));return null;}})))r.get();}var result=purchases.detail(c,p.id());assertEquals(result.status().equals("RESERVED")?1:0,held(f));assertTrue(Set.of("RESERVED","CANCELLED").contains(result.status()));}
 @Test void reservedRequestCannotCancelOrderImplicitly(){var c=customer();var f=fixture(2,2);var p=purchases.submit(c,place(f,1));purchases.process(event(p));problem("ORDER_CREATED",()->purchases.cancel(c,p.id(),new Cancel(UUID.randomUUID(),2)));assertEquals(1,held(f));var o=orders.detail(c,purchases.detail(c,p.id()).orderId());orders.cancel(c,o.id(),new Cancel(UUID.randomUUID(),1));assertEquals("RESERVED",purchases.detail(c,p.id()).status());assertEquals(0,held(f));}
 @Test void dueRequestTerminatesAndOriginalUUIDNeverStartsAgain(){var c=customer();var f=fixture(2,2);var body=place(f,1);var p=purchases.submit(c,body);due(p);assertTrue(purchases.process(event(p)));var result=purchases.detail(c,p.id());assertEquals("EXPIRED",result.status());assertEquals(result,purchases.submit(c,body));assertFalse(purchases.expire(p.id()));assertEquals(0,held(f));}
 @Test void expiryAndCancelWorkersCompeteOnce()throws Exception {var c=customer();var f=fixture(2,2);var p=purchases.submit(c,place(f,1));due(p);try(var pool=Executors.newFixedThreadPool(3)){for(var r:pool.invokeAll(List.<Callable<Object>>of(()->purchases.expire(p.id()),()->purchases.process(event(p)),()->{try{return purchases.cancel(c,p.id(),new Cancel(UUID.randomUUID(),1));}catch(Problem x){assertEquals("STALE_VERSION",x.code);return null;}})))r.get();}assertEquals("EXPIRED",purchases.detail(c,p.id()).status());assertEquals(2,purchases.detail(c,p.id()).version());assertEquals(0,held(f));}
 @Test void deadlineClipsToSalesEnd(){var c=customer();var f=fixture(2,2,OffsetDateTime.now().plusSeconds(10),true);var p=purchases.submit(c,place(f,1));assertEquals(f.session().salesEnd().toInstant(),p.deadlineAt().toInstant());}
 @Test void archivedAfterAcceptanceRejectsWithoutHold(){var c=customer();var f=fixture(2,2);var p=purchases.submit(c,place(f,1));catalog.transition(manager,f.event().id(),new Transition(UUID.randomUUID(),2L),false);purchases.process(event(p));assertEquals("SALES_CLOSED",purchases.detail(c,p.id()).reason());assertEquals(0,held(f));}
 @Test void synchronousOrdersAndPaidStockStillCountAgainstQuota(){var c=customer();var f=fixture(3,1);var p=purchases.submit(c,place(f,1));var o=orders.place(c,place(f,1));var paid=payments.start(c,o.id(),new PaymentModels.Pay(UUID.randomUUID(),1,1200,"SUCCESS"));payments.reconcile(c,o.id(),paid.payment().id(),new PaymentModels.Reconcile(UUID.randomUUID()));purchases.process(event(p));assertEquals("PURCHASE_LIMIT",purchases.detail(c,p.id()).reason());assertEquals(0,held(f));}
 @Test void fullPendingOrderLimitProducesDurableRejection(){var c=customer();for(int i=0;i<5;i++)orders.place(c,place(fixture(2,2),1));var f=fixture(2,2);var p=purchases.submit(c,place(f,1));purchases.process(event(p));assertEquals("ORDER_LIMIT",purchases.detail(c,p.id()).reason());assertEquals(0,held(f));}
 @Test void acceptanceQuoteAndDraftAreValidated(){var c=customer();var f=fixture(2,2);problem("QUOTE_CHANGED",()->purchases.submit(c,new Place(UUID.randomUUID(),f.ticket().id(),1,2,1200)));problem("QUOTE_CHANGED",()->purchases.submit(c,new Place(UUID.randomUUID(),f.ticket().id(),1,1,1)));problem("SALES_CLOSED",()->purchases.submit(c,place(fixture(2,2,OffsetDateTime.now().plusHours(1),false),1)));assertEquals(0,count("purchase_request",c.id()));}
 @Test void disabledOrLoggedOutAcceptedIdentityCannotProduceOrder(){var f=fixture(2,2);var a=customer();var p=purchases.submit(a,place(f,1));db.update("UPDATE customer_account SET enabled=false WHERE id=?",a.id());purchases.process(event(p));assertEquals("REJECTED",db.queryForObject("SELECT status FROM purchase_request WHERE id=?",String.class,p.id()));db.update("UPDATE customer_account SET enabled=true WHERE id=?",a.id());problem("UNAUTHENTICATED",()->purchases.detail(a,p.id()));var b=customer();var q=purchases.submit(b,place(f,1));db.update("DELETE FROM customer_session WHERE token_hash=?",b.sessionHash());purchases.process(event(q));assertEquals("UNAUTHENTICATED",db.queryForObject("SELECT reason FROM purchase_request WHERE id=?",String.class,q.id()));assertEquals(0,held(f));}
 @Test void disablingAcceptanceAllowsReadReplayCancelAndProcessingAcceptedIntent(){var c=customer();var f=fixture(3,3);var body=place(f,1);var p=purchases.submit(c,body);var off=new PurchaseService(db,orders,new AdmissionService(db,redis,json,new AdmissionSettings(false,"encore-demo-off",1,2,2,5,10,30,5)),false,false,60);var tx=new TransactionTemplate(transactions);assertEquals(p,tx.execute(s->off.submit(c,body)));problem("PURCHASE_DISABLED",()->tx.execute(s->off.submit(c,place(f,1))));assertEquals(Boolean.TRUE,tx.execute(s->off.process(event(p))));var q=purchases.submit(c,place(f,1));assertEquals("CANCELLED",tx.execute(s->off.cancel(c,q.id(),new Cancel(UUID.randomUUID(),1))).status());}
 @Test void outboxInsertionFailureRollsBackAcceptanceAndOriginalCanRetry(){var c=customer();var f=fixture(2,2);var body=place(f,1);db.execute("ALTER TABLE purchase_outbox ADD CONSTRAINT m4a_outbox_fault CHECK(event_type<>'PURCHASE_REQUESTED') NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->purchases.submit(c,body));assertEquals(0,count("purchase_request",c.id()));assertEquals(0,count("purchase_command",c.id()));assertEquals(0,held(f));}finally{db.execute("ALTER TABLE purchase_outbox DROP CONSTRAINT m4a_outbox_fault");}assertNotNull(purchases.submit(c,body));}
 @Test void finalTransitionFailureRollsBackOrderHeldCommandAndLedger(){var c=customer();var f=fixture(2,2);var p=purchases.submit(c,place(f,1));db.execute("ALTER TABLE purchase_request ADD CONSTRAINT m4a_finish_fault CHECK(NOT(id='"+p.id()+"'::uuid AND status='RESERVED')) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->purchases.process(event(p)));assertEquals("PROCESSING",purchases.detail(c,p.id()).status());assertEquals(0,count("ticket_order",c.id()));assertEquals(0,count("order_command",c.id()));assertEquals(0,held(f));}finally{db.execute("ALTER TABLE purchase_request DROP CONSTRAINT m4a_finish_fault");}assertTrue(purchases.process(event(p)));assertEquals(1,held(f));}
 @Test void ledgerFailureDoesNotAcknowledgeOrRejectAndCanRetry(){var c=customer();var f=fixture(2,2);var p=purchases.submit(c,place(f,1));db.execute("ALTER TABLE order_inventory_event ADD CONSTRAINT m4a_ledger_fault CHECK(ticket_id<>'"+f.ticket().id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->purchases.process(event(p)));assertEquals("PROCESSING",purchases.detail(c,p.id()).status());assertEquals(0,held(f));}finally{db.execute("ALTER TABLE order_inventory_event DROP CONSTRAINT m4a_ledger_fault");}assertTrue(purchases.process(event(p)));}
 @Test void requestDeadlineCheckedAfterActuallyWaitingOnTicketLock()throws Exception {var c=customer();var f=fixture(2,2);var p=purchases.submit(c,place(f,1));db.update("UPDATE purchase_request SET deadline_at=created_at+interval '3 seconds' WHERE id=?",p.id());try(var pool=Executors.newSingleThreadExecutor()){new TransactionTemplate(transactions).execute(s->{db.queryForObject("SELECT id FROM ticket_type WHERE id=? FOR UPDATE",UUID.class,f.ticket().id());var task=pool.submit(()->purchases.process(event(p)));boolean waiting=false;for(int i=0;i<70;i++){db.execute("SELECT pg_stat_clear_snapshot()");if(db.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE '%FOR UPDATE OF t%'",Integer.class)>0){waiting=true;break;}try{Thread.sleep(30);}catch(Exception e){throw new AssertionError(e);}}assertTrue(waiting);try{Thread.sleep(Math.max(1,Duration.between(OffsetDateTime.now(),p.createdAt().plusSeconds(3)).toMillis()+100));}catch(Exception e){throw new AssertionError(e);}s.setRollbackOnly();return task;}).get(4,TimeUnit.SECONDS);}assertEquals("EXPIRED",purchases.detail(c,p.id()).status());assertEquals(0,held(f));}
 @Test void unknownOutboxEventCannotProcessAndConstraintsRejectInvalidState(){assertFalse(purchases.process(UUID.randomUUID()));var c=customer();var p=purchases.submit(c,place(fixture(2,2),1));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("UPDATE purchase_request SET status='RESERVED',version=2,closed_at=clock_timestamp() WHERE id=?",p.id()));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("INSERT INTO purchase_outbox SELECT * FROM purchase_outbox WHERE purchase_id=?",p.id()));}
 @Test void httpRequiresCustomerCsrfRejectsSpoofAndReturns202Location()throws Exception {mvc.perform(get("/api/customer/purchases")).andExpect(status().isUnauthorized());var issue=customers.register("pw-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());var cookie=new Cookie("TICKET_CUSTOMER_SESSION",issue.token());var f=fixture(2,2);String body=json.writeValueAsString(place(f,1));mvc.perform(post("/api/customer/purchases").cookie(cookie).contentType("application/json").content(body)).andExpect(status().isForbidden());var csrf=mvc.perform(get("/api/customer/auth/csrf")).andReturn();var n=json.readTree(csrf.getResponse().getContentAsString());var csrfCookie=csrf.getResponse().getCookie("TICKET_CUSTOMER_CSRF");mvc.perform(post("/api/customer/purchases").cookie(cookie,csrfCookie).header(n.get("headerName").asText(),n.get("token").asText()).contentType("application/json").content(body.substring(0,body.length()-1)+",\"customerId\":\"spoof\"}")).andExpect(status().isBadRequest());mvc.perform(post("/api/customer/purchases").cookie(cookie,csrfCookie).header(n.get("headerName").asText(),n.get("token").asText()).contentType("application/json").content(body)).andExpect(status().isAccepted()).andExpect(header().string("Location",org.hamcrest.Matchers.startsWith("/api/customer/purchases/"))).andExpect(jsonPath("$.status").value("PROCESSING")).andExpect(jsonPath("$.sessionHash").doesNotExist()).andExpect(jsonPath("$.customerId").doesNotExist()).andExpect(jsonPath("$.orderId").isEmpty());}
 @Test void acceptedQualificationDoesNotNeedRedisAgainAtProcessing(){var c=customer();var f=fixture(2,2);var gate=new AdmissionService(db,redis,json,new AdmissionSettings(true,"encore-demo-m4a-accepted",1,2,2,5,10,30,5));var svc=new PurchaseService(db,orders,gate,true,true,60);var tx=new TransactionTemplate(transactions);var body=place(f,1);problem("ADMISSION_REQUIRED",()->tx.execute(s->svc.submit(c,body)));tx.execute(s->gate.join(c,f.ticket().id(),new AdmissionService.Join(UUID.randomUUID())));var p=tx.execute(s->svc.submit(c,body));redis.delete(gate.keys(f.ticket().id()));assertEquals(p,tx.execute(s->svc.submit(c,body)));assertTrue(purchases.process(event(p)));assertEquals("RESERVED",purchases.detail(c,p.id()).status());assertEquals(1,held(f));}
 @Test void admissionTypeFailureDoesNotPersistAcceptanceOrOutbox(){var c=customer();var f=fixture(2,2);var gate=new AdmissionService(db,redis,json,new AdmissionSettings(true,"encore-demo-m4a-fault",1,2,2,5,10,30,5));var svc=new PurchaseService(db,orders,gate,true,true,60);var tx=new TransactionTemplate(transactions);redis.opsForValue().set(gate.keys(f.ticket().id()).get(2),"synthetic wrong type");try{problem("ADMISSION_UNAVAILABLE",()->tx.execute(s->svc.submit(c,place(f,1))));assertEquals(0,count("purchase_request",c.id()));assertEquals(0,held(f));}finally{redis.delete(gate.keys(f.ticket().id()));}}
 @Test void cancellationUUIDCannotBeReusedAsOrderCommand(){var c=customer();var f=fixture(2,2);var p=purchases.submit(c,place(f,1));var cancel=new Cancel(UUID.randomUUID(),1);purchases.cancel(c,p.id(),cancel);problem("REQUEST_CONFLICT",()->orders.place(c,new Place(cancel.requestId(),f.ticket().id(),1,1,1200)));assertEquals(0,held(f));}

 @Test void acceptanceRechecksAuthAfterActualForeignKeyLockWait()throws Exception {var c=customer();var f=fixture(2,2);db.update("UPDATE customer_session SET expires_at=clock_timestamp()+interval '2 seconds' WHERE token_hash=?",c.sessionHash());try(var pool=Executors.newSingleThreadExecutor()){new TransactionTemplate(transactions).execute(s->{db.queryForObject("SELECT id FROM ticket_type WHERE id=? FOR UPDATE",UUID.class,f.ticket().id());var task=pool.submit(()->problem("UNAUTHENTICATED",()->purchases.submit(c,place(f,1))));boolean waiting=false;for(int i=0;i<60;i++){db.execute("SELECT pg_stat_clear_snapshot()");if(db.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE 'INSERT INTO purchase_request%'",Integer.class)>0){waiting=true;break;}try{Thread.sleep(20);}catch(Exception e){throw new AssertionError(e);}}assertTrue(waiting);try{Thread.sleep(2100);}catch(Exception e){throw new AssertionError(e);}s.setRollbackOnly();return task;}).get(4,TimeUnit.SECONDS);}assertEquals(0,count("purchase_request",c.id()));assertEquals(0,count("purchase_command",c.id()));assertEquals(0,held(f));}

 @Test void terminalStatesRequireNonNullClosedTimestamp(){var c=customer();var f=fixture(2,2);var p=purchases.submit(c,place(f,1));purchases.cancel(c,p.id(),new Cancel(UUID.randomUUID(),1));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("UPDATE purchase_request SET closed_at=NULL WHERE id=?",p.id()));var q=purchases.submit(c,place(f,1));purchases.process(event(q));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("UPDATE purchase_request SET closed_at=NULL WHERE id=?",q.id()));}

}
